// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version:
//
// 1) Reorder loops to i-k-j to reuse A[k][i] across all j and
//    to access whole rows of B contiguously:
//      for (i)
//        for (k = i+1 .. M-1) {
//          tmp = A[k][i];
//          for (j)
//            B[i][j] += tmp * B[k][j];
//        }
//
// 2) Apply the scaling B[i][j] *= alpha in a separate pass:
//
//      for (i,j) B[i][j] *= alpha;
//
// This reordering is algebraically equivalent and still uses only
// the original (unscaled) values B[k][j] on the right-hand side.
// The traversal is fully expressed via Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// Step 1: triangular update
	//   B[i][j] += sum_{k > i} A[k][i] * B[k][j]
	// ------------------------------------------------------------------
	//
	// We traverse the joint structure (A,B) over dimensions 'i', 'k', 'j':
	//  - outer:  i   (row index of the destination row of B)
	//  - middle: k   (row index in A and in the source row of B)
	//  - inner:  j   (column index, contiguous in B)
	//
	// For each (i,k) with k > i we:
	//   - load a_ki = A[k][i] once
	//   - walk j in a single inner for_each, updating an entire row
	//     segment B[i][*] using the row B[k][*].
	//
	// This improves data locality compared to the original i-j-k order:
	//  - A[k][i] is reused across all j.
	//  - B[i][j] and B[k][j] are streamed row-wise (good for caches
	//    and SIMD vectorization).
	traverser(A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'k' and 'j' remain (in some order).
		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// Iterate over all k; we only use k > i_idx.
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, 'j' remains.
			auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// Original kernel uses k in [i+1, M), so skip k <= i.
			if (k_idx <= i_idx)
				return; // no contributions for this (i,k)

			// A[k][i] -> A at (i = k, k = i)
			const num_t a_ki = A[noarr::idx<'i', 'k'>(k_idx, i_idx)];

			// Inner j-loop: walk all columns j for this (i,k) pair.
			// trav_ik.for_each iterates over the remaining free
			// dimension(s), which here is exactly 'j'.
			trav_ik.for_each([&](auto state_ikj) {
				const std::size_t j_idx = get_index<'j'>(state_ikj);

				// States for B[i][j] and B[k][j]
				const auto Bij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);
				const auto Bkj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

				B[Bij_state] += a_ki * B[Bkj_state];
			});
		});
	});

	// ------------------------------------------------------------------
	// Step 2: scaling B by alpha
	//   B[i][j] = alpha * B[i][j]
	// ------------------------------------------------------------------
	//
	// In the original algorithm, each B[i][j] is scaled by alpha
	// immediately after accumulating all contributions for that row
	// element. Since no later computation reads any already-updated
	// B[i][j] on the right-hand side, this global post-scaling is
	// algebraically equivalent:
	//
	//   B_final = alpha * (B_original + strictly_lower(A) * B_original).
	//
	// This separate pass is also a simple, fully vectorizable sweep.
	traverser(B).for_each([&](auto state) {
		B[state] *= alpha;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
