using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Layouts are chosen so that:
	//  - dimension 'i' is the innermost (contiguous) dimension
	//    in both A and B. This gives unit-stride accesses in the
	//    k-loop inside the kernel (we iterate k along 'i').
	//
	// A: i x k  (M x M), 'i' inner, 'k' outer
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ k_vec);

	// B: i x j  (M x N), 'i' inner, 'j' outer
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

