void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	// A: i x k, square M x M
	// B: i x j, M x N

	alpha = (num_t)1.5;

	const int m_len = static_cast<int>(A | get_length<'i'>());
	const int n_len = static_cast<int>(B | get_length<'j'>());

	// Initialize A: unit lower-triangular
	// for (i = 0; i < m; i++) {
	//   for (j = 0; j < i; j++) A[i][j] = ((i + j) % m) / m;
	//   A[i][i] = 1.0;
	// }
	noarr::traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		int ii = static_cast<int>(i);
		int kk = static_cast<int>(k);

		if (kk < ii) {
			A[state] = (num_t)((ii + kk) % m_len) / (num_t)m_len;
		} else if (kk == ii) {
			A[state] = (num_t)1.0;
		}
		// For kk > ii we leave A[state] uninitialized, matching the C code
	});

	// Initialize B
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++)
	//     B[i][j] = ((n + (i - j)) % n) / n;
	noarr::traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);

		B[state] = (num_t)(((n_len + (ii - jj)) % n_len)) / (num_t)n_len;
	});
}

// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimizations in this version:
//
// 1) Data layout:
//    - A layout is (i inner, k outer)
//    - B layout is (i inner, j outer)
//    This makes the 'i' dimension contiguous for both A and B.
//
//    In the kernel, for fixed (i,j) we iterate k and access:
//      A[k][i]  -> (i-dim = k, k-dim = i)
//      B[k][j]  -> (i-dim = k, j-dim = j)
//    so the k-loop walks the innermost (contiguous) 'i' dimension.
//
// 2) Loop order:
//    - We legally interchange the i and j loops:
//
//        for i
//          for j
//            for k
//
//      ->  for j
//            for i
//              for k
//
//      Columns j are independent of each other and, for fixed j,
//      the computations for different i values only depend on B[k][j]
//      with k > i, which are still at their original values when i is
//      processed in ascending order. Thus semantics are preserved.
//
//    - We traverse B with a Noarr traverser over 'j' (columns) first,
//      and then over 'i' (rows), which matches the chosen data layout.
//
// 3) State reuse in the k-loop:
//    - For a given (i,j) we build base states for column i of A and
//      column j of B and then only vary the 'i' index, avoiding
//      repeatedly constructing full 2D states inside the k-loop.
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>();

	#pragma scop
	// Traverse B column by column: outer dimension 'j', inner 'i'.
	// This matches `tuning.b_layout` where 'i' is the innermost dimension.
	noarr::traverser(B).template for_dims<'j'>([=](auto trav_j) {
		// trav_j: 'j' is fixed, remaining dimension is 'i'
		trav_j.for_each([=](auto state_ij) {
			const std::size_t i = get_index<'i'>(state_ij);
			const std::size_t j = get_index<'j'>(state_ij);

			num_t Bij = B[state_ij];

			// Base states for the k-loop:
			//  - a_base: column "i" of A, we will vary the 'i' index (row)
			//  - b_col_base: column "j" of B, again varying the 'i' index
			const auto a_base     = noarr::idx<'i', 'k'>(std::size_t(0), i);
			const auto b_col_base = noarr::idx<'i', 'j'>(std::size_t(0), j);

			// k-loop: for (k = i+1; k < M; k++)
			for (std::size_t k = i + 1; k < m_len; ++k) {
				// Only the 'i' coordinate changes with k. We add this
				// offset to the pre-built base states.
				const auto k_state  = noarr::idx<'i'>(k);
				const auto a_state  = a_base + k_state;      // A[k][i]
				const auto bkj_state = b_col_base + k_state; // B[k][j]

				Bij += A[a_state] * B[bkj_state];
			}

			Bij *= alpha;
			B[state_ij] = Bij;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

