// Main computational kernel
// Original C (Polybench):
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version below:
//  - Uses Noarr traversers for all dimension loops (i, j, k)
//  - Reorders loops to (k, i, j) to improve spatial locality in B:
//        for k
//          for i < k
//            for j
//              B[i][j] += A[k][i] * B[k][j];
//  - Then performs a separate pass scaling B by alpha.
//    This is algebraically equivalent to the original kernel:
//        B_final[i][j] = alpha * ( B0[i][j] + sum_{k>i} A[k][i]*B0[k][j] )
//    (B0 is the initial value of B).
//  - The dependence pattern is preserved: whenever B[k][j] is used
//    on the right-hand side, it has not been updated yet in our
//    re-ordered traversal (see analysis in comments).
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// Triangular matrix–matrix multiply: accumulate A^T * B into B.
	// Outer loop over k (one row of A / one "source" row of B at a time).
	traverser(A, B).template for_dims<'k'>([&](auto trav_k) {
		// k is fixed in trav_k
		auto k = get_index<'k'>(trav_k.state());

		// Next loop over i. We will only use the strictly lower-triangular
		// region, i.e. i < k. For each (k, i) we then sweep all j.
		trav_k.template for_dims<'i'>([&](auto trav_ki) {
			auto state_ki = trav_ki.state();
			auto i = get_index<'i'>(state_ki);

			// Only consider strictly lower part: i < k.
			if (i >= k)
				return;

			// A is stored with dimensions ('i','k') and we need A[k][i],
			// i.e. indices swapped relative to the storage layout.
			// Construct the appropriate state explicitly:
			num_t a_ki = A[noarr::idx<'i', 'k'>(k, i)];

			// For this fixed (k, i), iterate all columns j.
			// trav_ki has 'i' and 'k' fixed, so for_each iterates 'j'.
			trav_ki.for_each([&](auto state_ijk) {
				// Left-hand side element: B[i][j]
				num_t Bij = B[state_ijk];

				auto j = get_index<'j'>(state_ijk);

				// Right-hand side element: B[k][j]
				// We only need dimensions ('i','j') for B, extra 'k' in
				// the state is ignored by B's layout.
				auto state_kj = noarr::idx<'i', 'j'>(k, j);

				Bij += a_ki * B[state_kj];
				B[state_ijk] = Bij;
			});
		});
	});

	// Final scaling pass: B[i][j] = alpha * B[i][j].
	// This is independent of the previous accumulation and matches the
	// original semantics where scaling was done after the k-loop.
	traverser(B).for_each([&](auto state) {
		B[state] *= alpha;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
