// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// We transform it algebraically into an equivalent form:
//
//   // 1) accumulate all A[k][i] * B[k][j] contributions
//   for (k = 1; k < M; k++)
//     for (i = 0; i < k; i++)
//       for (j = 0; j < N; j++)
//         B[i][j] += A[k][i] * B[k][j];  // B[k][j] is still the original value
//
//   // 2) final scaling
//   for (i = 0; i < M; i++)
//     for (j = 0; j < N; j++)
//       B[i][j] *= alpha;
//
// This reordering is safe because:
//   * In the original code, all products A[k][i] * B[k][j] always use the
//     original, unmodified B[k][j]. Our reordered loop also never modifies
//     row k while it is being used as a source row.
//   * Updates to B[i][j] are purely accumulative (+=), and multiplication
//     by alpha is a final, independent step.
// The new order improves locality: for each (k, i) pair we sweep the full
// row over j, accessing B[i][j] and B[k][j] contiguously.
//
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	// Helper view of B where the row dimension is named 'k' instead of 'i'.
	// This lets us share the 'k' dimension between A and B_k for the source row.
	//
	//   B      : dims ('i', 'j')  -> B[i][j]
	//   B_k    : dims ('k', 'j')  -> B[k][j]  (same underlying data)
	//
	auto B_k = B ^ noarr::rename<'i', 'k'>();

	#pragma scop
	// ---------------------------------------------------------------------
	// 1) Accumulate triangular contributions:
	//    for (k = 1..M-1) for (i = 0..k-1) for (j)
	//      B[i][j] += A[k][i] * B[k][j]
	// ---------------------------------------------------------------------
	//
	// We use a joint traverser over (A, B, B_k). The union of dimensions is
	// ('i', 'j', 'k'). We explicitly drive 'k' and then 'i'; the remaining
	// free dimension 'j' is iterated by for_each, giving the desired
	// nesting: k (outer) -> i -> j (inner).
	//
	traverser(A, B, B_k).template for_dims<'k'>([&](auto trav_k) {
		// trav_k: 'k' fixed, 'i' and 'j' free where present

		trav_k.template for_dims<'i'>([&](auto trav_ki) {
			// trav_ki: 'k' and 'i' fixed, 'j' free

			// Extract the (i,k) indices for this pair.
			auto state_ki = trav_ki.state();
			auto ii = get_index<'i'>(state_ki);
			auto kk = get_index<'k'>(state_ki);

			// We only want pairs with i < k. This matches the original
			// inner loop "for (k = i+1; k < M; ++k)" and also ensures
			// we only access the initialized (lower triangular) part of A.
			if (ii >= kk)
				return; // skip this (i,k) pair

			// A is laid out as (i x k): row 'i', column 'k'.
			// We need A[k][i], i.e. row = k, column = i.
			auto a_state = noarr::idx<'i', 'k'>(kk, ii);
			num_t Aki = A[a_state];

			// Now sweep over all columns j for this fixed (i,k) pair:
			//   B[i][j] += A[k][i] * B[k][j]
			trav_ki.for_each([&](auto state_ikj) {
				// B uses ('i','j'); B_k uses ('k','j').
				// state_ikj contains ('i','k','j'), so each bag ignores
				// the dimension it does not need.
				B[state_ikj] += Aki * B_k[state_ikj];
			});
		});
	});

	// ---------------------------------------------------------------------
	// 2) Final scaling:
	//    B[i][j] *= alpha;
	// ---------------------------------------------------------------------
	traverser(B).for_each([&](auto state) {
		B[state] *= alpha;
	});
	#pragma endscop
}

